for(const Type of[G.GraphvizSize,G.GraphvizSizeF])test(`${Type.name}Tests full size/default/string assertions`,()=>{assert.equal(new Type().ToString(),'0x0');for(const[w,h]of[[0,0],[0,10],[10,0],[10,15],[30,25]]){const s=new Type(w,h);assert.equal(s.Width,w);assert.equal(s.Height,h);assert.equal(s.IsEmpty,w===0||h===0);assert.equal(s.ToString(),`${w}x${h}`);}for(const[w,h]of[[-1,10],[10,-2],[-5,-2]])assert.throws(()=>new Type(w,h));if(Type===G.GraphvizSizeF)assert.equal(new Type(12.2,25.6).ToString(),'12.2x25.6');});
