test('Record collections, cells, port and text property semantics',()=>{const cells=new G.GraphvizRecordCellCollection(),first=new G.GraphvizRecordCell();assert.equal(cells.Count,0);cells.Add(first);assert.deepEqual([...cells],[first]);assert.deepEqual([...new G.GraphvizRecordCellCollection(cells)],[first]);assert.deepEqual([...new G.GraphvizRecordCellCollection([first])],[first]);assert.throws(()=>new G.GraphvizRecordCellCollection(null));for(const record of[new G.GraphvizRecord(),first]){record.Cells=cells;assert.equal(record.Cells,cells);assert.throws(()=>{record.Cells=null;});}for(const property of['Port','Text']){const cell=new G.GraphvizRecordCell();for(const v of[null,'']){cell[property]=v;assert.equal(cell['Has'+property],false);assert.equal(cell[property],v);}cell[property]='Test'+property;assert.equal(cell['Has'+property],true);assert.equal(cell[property],'Test'+property);}});
// upstream: tests/QuikGraph.Graphviz.Tests/Dot/GraphvizVertexTests.cs::ToDot_InvariantCulture
