test('DOT numeric properties retain invariant decimal separators',()=>{const vertex=new G.GraphvizVertex(),edge=new G.GraphvizEdge(),graph=new G.GraphvizGraph();vertex.PenWidth=0.25;edge.Weight=12.5;graph.RankSeparation=0.75;assert.equal(vertex.ToDot(),'penwidth=0.25');assert.equal(edge.ToDot(),'weight=12.5');assert.equal(graph.ToDot(),'ranksep=0.75');assert.equal(vertex.ToString(),vertex.ToDot());assert.equal(edge.ToString(),edge.ToDot());assert.equal(graph.ToString(),graph.ToDot());});
